import{d as c,C as t,o as g,c as u,j as a,a as r,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十八章","description":"以水的柔弱与攻坚之用贯通承担国辱、国患，分读王注与正言若反。","frontmatter":{"title":"道德经第七十八章","description":"以水的柔弱与攻坚之用贯通承担国辱、国患，分读王注与正言若反。","category":"guide","aliases":["道德经第七十八章","老子第七十八章","dao de jing chapter 78"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-78.md","filePath":"daoism/dao-de-jing/chapter-78.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-78.md"},y=c({...m,setup(p){const i=[{id:"water-and-irreplaceable-use",label:"天下莫柔弱于水",showLabel:!0,sentences:[["天下莫",{text:"柔弱",glossary:"rouruo"},"于水，而攻",{text:"坚强",glossary:"jianqiang-rigid"},"者莫之能",{text:"胜",glossary:"sheng-overcome"},"，其无以",{text:"易",glossary:"yi-easy"},"之。"]],note:["【白话】天下没有比水更柔弱的，可是在攻克坚硬之物方面，没有什么能胜过它，因为没有别的东西能替代它的这种功用。","【王弼注择要】「其谓水也。言用水之柔弱，无物可以易之也。」","【读法】易是替代，之依注指水，重点在用水之柔弱。水的取象强调柔能成用，不能因此宣称水或弱者在一切情境下都无条件取胜。"]},{id:"knowing-and-practicing",label:"弱之胜强，柔之胜刚",showLabel:!0,sentences:[["弱之",{text:"胜",glossary:"sheng-overcome"},"强，柔之",{text:"胜",glossary:"sheng-overcome"},"刚，天下莫不知，莫能行。"]],note:["【白话】弱可以胜强，柔可以胜刚，天下没有人不知道这个道理，却没有人能实行。知与行的反差，是本章转入治理例子的关节。","【读法】莫不知、莫能行采用强烈概括的语气，提醒守柔实践之难；不把它统计成人人都懂、现实无人做到的经验结论。"]},{id:"bearing-public-disgrace",label:"受国之垢",showLabel:!0,sentences:[["是以圣人云：受国之",{text:"垢",glossary:"gou-disgrace"},"，是谓",{text:"社稷",glossary:"sheji"},"主；"]],note:["【白话】所以圣人说：能承担一国耻辱的人，才称得上国家的主持者。垢从污垢引申为辱名，受强调承担。","【读法】本句以下所据未另见逐句王注，依字面与上下文解释。社稷保留古代国家与祭祀的语境，不把承担国辱改成追求个人光彩。"]},{id:"bearing-public-calamity",label:"受国不祥",showLabel:!0,sentences:[["受国",{text:"不祥",glossary:"buxiang"},"，是为天下王。"]],note:["【白话】能承担一国灾患的人，才配作天下的王。前面的辱与这里的患相连，把居上者的责任放在承受困难上。","【读法】本站是为天下王，所据作是谓天下王，保留本站现文并注明。今天相参时，承担公共责任与要求处于弱势的人默受伤害，必须分清。"]},{id:"upright-words-seem-reversed",label:"正言若反",showLabel:!0,sentences:[["正言若反。"]],note:["【白话】正当的话听起来仿佛说反了。能攻坚的是柔水，能为主的是受辱受患者，都违背逞强避辱的惯常想法。","【读法】若是仿佛，反须连前文的价值转向理解。并非一切反常、悖理的话都因此正确，也不能靠令人惊异来替代理由。"]}],s=[{id:"rouruo",term:"柔弱",sense:1},{id:"jianqiang-rigid",term:"坚强",sense:1},{id:"sheng-overcome",term:"胜",sense:1},{id:"yi-easy",term:"易",sense:3},{id:"gou-disgrace",term:"垢",sense:1},{id:"sheji",term:"社稷",sense:1},{id:"buxiang",term:"不祥",sense:2}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十八章",tabindex:"-1"},[r("道德经第七十八章 "),a("a",{class:"header-anchor",href:"#道德经第七十八章","aria-label":'Permalink to "道德经第七十八章"'},"​")],-1)),o(n,{title:"水的柔弱，怎样转到承担一国之重",summary:"本章从水最柔弱、却能攻坚起笔，随即指出人人知道守柔之理，却难实行。治理者的例子把守柔落实为受国之垢、受国不祥：承担一国之辱与灾患。结尾正言若反，提示正当的话可能违背好强避辱的习惯判断。",points:[{label:"先读",text:"先分辨水柔弱的形态与攻坚的功用。"},{label:"再辨",text:"从莫不知转到莫能行，看难处怎样落到承担。"},{label:"后看",text:"受国之垢说治理者责任，不能转嫁为要求受害者忍受伤害。"}],hint:"易读 yì，取替换义；垢读 gòu，社稷读 shè jì。不祥此处指灾患，正言若反仍须连前文判断。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"其无以易之。",tone:"先辨易字",guide:"所说没有可替代者，连水的柔弱之用理解。"},{text:"天下莫不知，莫能行。",tone:"从知道转到实行",guide:"后面受辱受患的例子说明实践的难处。"},{text:"受国之垢，是谓社稷主。",tone:"把居上连于承担",guide:"治理者能否受辱承患，比自显威势更值得问。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-水为什么是本章的起点" tabindex="-1">象：水为什么是本章的起点？ <a class="header-anchor" href="#象-水为什么是本章的起点" aria-label="Permalink to &quot;象：水为什么是本章的起点？&quot;">​</a></h3><p>水呈现柔弱却能攻坚的反差。王注特别说明用水之柔弱，将形态与功用接起来；这为后文柔能担当提供形象，而不是证明弱小天然占优。</p><h3 id="理-受国之垢怎样承接柔胜刚" tabindex="-1">理：受国之垢怎样承接柔胜刚？ <a class="header-anchor" href="#理-受国之垢怎样承接柔胜刚" aria-label="Permalink to &quot;理：受国之垢怎样承接柔胜刚？&quot;">​</a></h3><p>守柔不只是一种外表姿态，还涉及不急于把耻辱和灾患推给别人。经文把这种承担放在社稷主、天下王身上，保留了治理与责任的明确对象。</p><h3 id="用-正言若反能否用来证明反常观点" tabindex="-1">用：正言若反能否用来证明反常观点？ <a class="header-anchor" href="#用-正言若反能否用来证明反常观点" aria-label="Permalink to &quot;用：正言若反能否用来证明反常观点？&quot;">​</a></h3><p>不能。先看具体主张如何与前文、事实和责任关系相接，再判断它是否成立。反常只能提示重新思考，不能自行充当正确的证据。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把担当落实为可承担的后果。</strong> 当结果不如预期时，居于决定位置的人应说明自己的选择和补救办法，避免将代价一层层推向没有决定权的人。</p><p><strong>区分守柔与失去边界。</strong> 保持回应与调整的空间，同时拒绝持续伤害；承担应与角色、能力和责任相称，不能借古文取消必要保护。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我所理解的守柔，是否包括面对不利后果？哪些责任该由我承担，哪些伤害则需要明确边界？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与古注据卷四 010b 电子录文核对。</li><li>本站是为天下王，录文作是谓天下王；正文、标点、别名保留。</li><li>王注明确的水之用与易之义择引；录文以用也等短句不猜校，后半未另造逐句古注。</li><li>受辱、受患与古代治国责任相连，现代启发另列；正言若反不泛化为反常即正确。</li><li>古注节引转简体并加标点，尚未逐字核对影印；白话、古注与现代启发分层。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，010b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
